# Fix slicing syntax
def get_freq_by_quadrant(grid):
    h, w = len(grid), len(grid[0])
    mid_r, mid_c = h//2, w//2

    quarters = {
        'top-left': [],
        'top-right': [],
        'bottom-left': [],
        'bottom-right': []
    }

    for r in range(mid_r):
        for c in range(mid_c):
            quarters['top-left'].append(grid[r][c])

    for r in range(mid_r):
        for c in range(mid_c, w):
            quarters['top-right'].append(grid[r][c])

    for r in range(mid_r, h):
        for c in range(mid_c):
            quarters['bottom-left'].append(grid[r][c])

    for r in range(mid_r, h):
        for c in range(mid_c, w):
            quarters['bottom-right'].append(grid[r][c])

    return quarters

